new_code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    # Outline the bounding rectangle, and extend any interior row/column
    # that has at least two markers away from the rectangle's boundary.
    active_rows = {r for r in range(r0 + 1, r1)
                   if sum(grid[r][c] != bg for c in range(c0 + 1, c1)) >= 2}
    active_cols = {c for c in range(c0 + 1, c1)
                   if sum(grid[r][c] != bg for r in range(r0 + 1, r1)) >= 2}
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1) or r in active_rows or c in active_cols):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
'''
